/// <summary>
/// Scoped service that tracks low-stock alert counts per circuit.
/// Components subscribe to OnChange to react when new data arrives.
/// Scoped lifetime ensures each user circuit has independent state.
/// </summary>
public class InventoryAlertService
{
    private readonly Random _random = new();

    public int CurrentLowStockCount { get; private set; }
    public string? CurrentWarehouseId { get; private set; }

    public event Action? OnChange;

    /// <summary>
    /// Simulates a database query returning a random low-stock count.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Fetches new data and notifies all subscribers.
    /// Called by the polling component; all other subscribers react via OnChange.
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        CurrentWarehouseId = warehouseId;
        CurrentLowStockCount = await GetLowStockCountAsync(warehouseId);
        OnChange?.Invoke();
    }
}

