@* Interactive dropdown for selecting the current warehouse.
   Rendered inside the static MainLayout but given its own render mode
   so it can handle change events. Updates the CascadingValueSource
   which notifies all [CascadingParameter] subscribers app-wide. *@

@rendermode InteractiveServer
@inject CascadingValueSource<WarehouseInfo> WarehouseSource
@using sv_552cd2fd825f4af3b419b2a3b77e2c54.Services

<select class="form-select form-select-sm" style="width: auto;"
        value="@_selectedId" @onchange="OnWarehouseChanged">
    @foreach (var wh in WarehouseInfo.AvailableWarehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    private string _selectedId = "WH-001";

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        _selectedId = e.Value?.ToString() ?? "WH-001";
        var selected = WarehouseInfo.AvailableWarehouses
            .First(w => w.Id == _selectedId);

        // Push the new value to every [CascadingParameter] subscriber.
        await WarehouseSource.NotifyChangedAsync(
            new WarehouseInfo { Id = selected.Id, Name = selected.Name });
    }
}

@* Displays the current low-stock alert count as a Bootstrap badge.
   Subscribes to InventoryAlertService.OnChange so it updates
   whenever ANY component triggers a refresh — not just itself. *@

@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable
@using sv_552cd2fd825f4af3b419b2a3b77e2c54.Services

@if (AlertService.CurrentLowStockCount > 0)
{
    <span class="badge bg-danger rounded-pill ms-1">@AlertService.CurrentLowStockCount</span>
}
else
{
    <span class="badge bg-success rounded-pill ms-1">0</span>
}

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        // Wrap in InvokeAsync because the event may fire from a timer
        // callback on a non-Blazor thread.
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
    }
}

