@page "/dashboard"
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable
@using sv_552cd2fd825f4af3b419b2a3b77e2c54.Services

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-3" style="max-width: 26rem;">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>Low-Stock Alerts</strong>
        <span class="text-muted" style="font-size: 0.85rem;">
            Warehouse: @(_warehouse?.Name ?? "—")
        </span>
    </div>
    <div class="card-body text-center">
        @if (AlertService.CurrentLowStockCount > 5)
        {
            <h2 class="text-danger">@AlertService.CurrentLowStockCount items</h2>
            <p class="text-danger mb-0">⚠ Attention needed — multiple items below minimum levels</p>
        }
        else if (AlertService.CurrentLowStockCount > 0)
        {
            <h2 class="text-warning">@AlertService.CurrentLowStockCount items</h2>
            <p class="mb-0">Some items are running low</p>
        }
        else
        {
            <h2 class="text-success">0 items</h2>
            <p class="mb-0">All stock levels are healthy</p>
        }
    </div>
    <div class="card-footer text-muted" style="font-size: 0.8rem;">
        Polling every 10 seconds &bull; Last checked: @_lastChecked.ToString("HH:mm:ss")
    </div>
</div>

@code {
    [CascadingParameter]
    private WarehouseInfo? _warehouse { get; set; }

    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private DateTime _lastChecked = DateTime.Now;
    private Action? _handler;

    protected override void OnInitialized()
    {
        // Subscribe to updates so this component re-renders when
        // AlertService.RefreshAsync is called (even by itself).
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // Kick off polling only after the component is interactive.
            await StartPollingAsync();
        }
    }

    protected override async Task OnParametersSetAsync()
    {
        // Warehouse changed via the cascading value — restart polling
        // against the new warehouse immediately.
        if (_warehouse is not null && _warehouse.Id != AlertService.CurrentWarehouseId)
        {
            await RestartPollingAsync();
        }
    }

    private async Task StartPollingAsync()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        // Immediate first fetch
        await PollOnceAsync();

        _ = Task.Run(async () =>
        {
            try
            {
                while (await _timer.WaitForNextTickAsync(_cts.Token))
                {
                    await InvokeAsync(async () =>
                    {
                        await PollOnceAsync();
                    });
                }
            }
            catch (OperationCanceledException) { }
        });
    }

    private async Task RestartPollingAsync()
    {
        await StopPollingAsync();
        await StartPollingAsync();
    }

    private async Task PollOnceAsync()
    {
        if (_warehouse is null) return;
        _lastChecked = DateTime.Now;
        // RefreshAsync stores the count and fires OnChange,
        // which notifies EVERY subscriber (sidebar badge, this page, etc.)
        await AlertService.RefreshAsync(_warehouse.Id);
    }

    private async Task StopPollingAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
            _cts = null;
        }
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();
    }
}

